create table if not exists private.admin_emails(email text primary key check(email=lower(btrim(email))),created_at timestamptz not null default now());
alter table private.admin_emails enable row level security;
revoke all on private.admin_emails from public,anon,authenticated;
create or replace function private.provision_allowlisted_admin() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.email is not null and exists(select 1 from private.admin_emails e where e.email=lower(new.email)) then insert into private.site_admins(user_id) values(new.id) on conflict(user_id) do nothing; end if; return new; end; $$;
revoke all on function private.provision_allowlisted_admin() from public,anon,authenticated;
create trigger xcontent_provision_admin after insert or update of email on auth.users for each row execute function private.provision_allowlisted_admin();
create or replace function public.is_site_admin() returns boolean language sql stable security invoker set search_path='' as $$ select private.is_site_admin(); $$;
revoke all on function public.is_site_admin() from public,anon;
grant execute on function public.is_site_admin() to authenticated;
create policy "No client access to private admin registry" on private.site_admins for all to anon,authenticated using(false) with check(false);
create policy "No client access to private admin email allowlist" on private.admin_emails for all to anon,authenticated using(false) with check(false);
drop policy if exists "Published videos are public" on public.videos;
create policy "Published videos are public to visitors" on public.videos for select to anon using(status='published');
create policy "Published videos and admin drafts are visible to signed-in users" on public.videos for select to authenticated using(status='published' or (select private.is_site_admin()));
